insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000001', 'present-simple-a2', 'A2 · Habits', 'Habits and facts. Cue: every / usually / still.', 'A2', '{"usage":"When: habits, ownership, facts that stay true. Cue: every, usually, still — not right now.","forms":{"affirmative":"I/you/we/they + V · he/she/it + V-s/es","negative":"don''t / doesn''t + base verb","question":"Do / Does + subject + base verb?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"I ship small fixes every morning."},{"id":"ex-2","context":"Docs","sentence":"This service retries failed jobs."},{"id":"ex-3","context":"On-call","sentence":"She owns the payment webhook."},{"id":"ex-4","context":"On-call","sentence":"Nightly backups finish before dawn."},{"id":"ex-5","context":"Standup","sentence":"We review pull requests on Fridays."}],"tips":["he/she/it takes -s; don''t/doesn''t + base (not doesn''t goes).","WIP in this standup uses Present Continuous, not Simple."]}'::jsonb, 1, 1, 1, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000001', 'present-simple-b1', 'B1 · Pick the tense', 'Simple = habit/fact. Continuous = live now.', 'B1', '{"usage":"When: choose Simple vs Continuous. Cue: every/usually → Simple; right now / at the moment → Continuous.","forms":{"affirmative":"I/you/we/they + V · he/she/it + V-s/es","negative":"don''t / doesn''t + base verb","question":"Do / Does + subject + base verb?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"She reviews pull requests every Friday."},{"id":"ex-2","context":"Docs","sentence":"The gateway rejects unsigned tokens."},{"id":"ex-3","context":"Standup","sentence":"The weekly retro starts at 16:00."},{"id":"ex-4","context":"RFC","sentence":"He owns the billing pipeline."},{"id":"ex-5","context":"Standup","sentence":"I ship hotfixes on Mondays, but I am shipping this one now."}],"tips":["A schedule or owner stays Simple even if you mention today.","Do not use Simple for a ticket you are working this standup."]}'::jsonb, 1, 1, 2, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000001', 'present-simple-b2', 'B2 · Register', 'Policy, SLA, and stative verbs stay Simple.', 'B2', '{"usage":"When: contracts, SLAs, stative (own, need, mean). Cue: still / always in RFC English.","forms":{"affirmative":"I/you/we/they + V · he/she/it + V-s/es","negative":"don''t / doesn''t + base verb","question":"Do / Does + subject + base verb?"},"examples":[{"id":"ex-1","context":"RFC","sentence":"This change requires a dual-write window."},{"id":"ex-2","context":"RFC","sentence":"The worker owns the outbox table."},{"id":"ex-3","context":"Policy","sentence":"Production deploys need two approvals."},{"id":"ex-4","context":"RFC","sentence":"The API returns 409 on duplicate keys."},{"id":"ex-5","context":"RFC","sentence":"It means the cache is the source of truth."}],"tips":["Never mark is owning / is needing / is meaning as correct.","Written policy uses Simple, not a live Continuous snapshot."]}'::jsonb, 1, 1, 3, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000001', 'present-simple-c1', 'C1 · Timeline', 'Invariant = Simple. Live probe = Continuous.', 'C1', '{"usage":"When: incident. Cue: still / does not affect → Simple invariant; we are tracing → Continuous.","forms":{"affirmative":"I/you/we/they + V · he/she/it + V-s/es","negative":"don''t / doesn''t + base verb","question":"Do / Does + subject + base verb?"},"examples":[{"id":"ex-1","context":"Docs","sentence":"Checkout still charges the card on Stripe 402 retries."},{"id":"ex-2","context":"Docs","sentence":"p99 stays under 200ms when the cache is warm."},{"id":"ex-3","context":"RFC","sentence":"Platform owns the shared Kafka cluster."},{"id":"ex-4","context":"Incident","sentence":"The fallback does not cover EU-only SKUs."},{"id":"ex-5","context":"Review","sentence":"Does the cron still run after the cutover?"}],"tips":["Lock the invariant in Simple before you narrate the live hunt.","A clock stamp (at 14:02) is Past, not Simple."]}'::jsonb, 1, 1, 4, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000002', 'present-continuous-a2', 'A2 · Now', 'Live work. Cue: right now / at the moment.', 'A2', '{"usage":"When: work happening now or a temporary project. Cue: right now, at the moment, currently.","forms":{"affirmative":"am/is/are + V-ing","negative":"am not / isn''t / aren''t + V-ing","question":"Am/Is/Are + subject + V-ing?"},"examples":[{"id":"ex-1","context":"Incident","sentence":"We are investigating the outage."},{"id":"ex-2","context":"Ticket","sentence":"She is building the settings page."},{"id":"ex-3","context":"Standup","sentence":"They are pairing on the auth fix."},{"id":"ex-4","context":"Deploy","sentence":"I am watching the rollout."},{"id":"ex-5","context":"Calendar","sentence":"The team is discussing scope."}],"tips":["Form: am/is/are + V-ing. Do not use Simple for this standup WIP.","Stative verbs (own, need, know) stay Simple."]}'::jsonb, 1, 1, 1, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000006', 'a1000000-0000-4000-8000-000000000002', 'present-continuous-b1', 'B1 · Habit vs now', 'Continuous = live. Simple = habit/owner.', 'B1', '{"usage":"When: contrast live work with a habit. Cue: right now → Continuous; every / usually → Simple.","forms":{"affirmative":"am/is/are + V-ing","negative":"am not / isn''t / aren''t + V-ing","question":"Am/Is/Are + subject + V-ing?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"She is fixing the flaky test right now."},{"id":"ex-2","context":"Standup","sentence":"She fixes flaky tests every sprint."},{"id":"ex-3","context":"Standup","sentence":"We are watching the canary today."},{"id":"ex-4","context":"Calendar","sentence":"They are discussing scope in the room."},{"id":"ex-5","context":"Review","sentence":"Are you testing login at the moment?"}],"tips":["I own billing stays Simple; I am paging the host is Continuous.","today alone is not enough — say if the work is in progress."]}'::jsonb, 1, 1, 2, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000007', 'a1000000-0000-4000-8000-000000000002', 'present-continuous-b2', 'B2 · Diary', 'Calendar already booked → am meeting, not will.', 'B2', '{"usage":"When: a diary slot is locked. Cue: at 15:00 tomorrow + be + V-ing; will is a new decision.","forms":{"affirmative":"am/is/are + V-ing","negative":"am not / isn''t / aren''t + V-ing","question":"Am/Is/Are + subject + V-ing?"},"examples":[{"id":"ex-1","context":"Calendar","sentence":"We are starting the dual-write tomorrow at 10."},{"id":"ex-2","context":"Slack","sentence":"We are seeing elevated 500s in EU."},{"id":"ex-3","context":"Standup","sentence":"I am pairing on auth this afternoon."},{"id":"ex-4","context":"Review","sentence":"They are reviewing the RFC today."},{"id":"ex-5","context":"RFC","sentence":"The service owns the outbox."}],"tips":["Locked calendar uses Present Continuous, not will.","Okay, I will revert is a decision just made."]}'::jsonb, 1, 1, 3, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000008', 'a1000000-0000-4000-8000-000000000002', 'present-continuous-c1', 'C1 · War room', 'Live hunt = Continuous. Result so far = Perfect.', 'C1', '{"usage":"When: war room. Cue: we are failing over now vs we have mitigated so far.","forms":{"affirmative":"am/is/are + V-ing","negative":"am not / isn''t / aren''t + V-ing","question":"Am/Is/Are + subject + V-ing?"},"examples":[{"id":"ex-1","context":"War room","sentence":"We are seeing checkout 500s in EU right now."},{"id":"ex-2","context":"Slack","sentence":"I am starting a rollback in two minutes."},{"id":"ex-3","context":"Incident","sentence":"We are tracing the 429s on the gateway."},{"id":"ex-4","context":"Standup","sentence":"Platform is paging the primary for this SEV-1."},{"id":"ex-5","context":"Review","sentence":"We are still syncing the replica after failover."}],"tips":["Do not use Continuous for a result already in (use Perfect).","A finished stamp at 14:02 is Past Simple."]}'::jsonb, 1, 1, 4, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000009', 'a1000000-0000-4000-8000-000000000003', 'past-simple-a2', 'A2 · Finished', 'Closed time. Cue: yesterday / last night / at 14:02.', 'A2', '{"usage":"When: a finished action at a closed time. Cue: yesterday, last night, at 14:02. Not yet/already.","forms":{"affirmative":"V-ed / irregular past","negative":"didn''t + base verb","question":"Did + subject + base verb?"},"examples":[{"id":"ex-1","context":"Deploy","sentence":"We shipped the hotfix yesterday."},{"id":"ex-2","context":"Incident","sentence":"The API went down at noon."},{"id":"ex-3","context":"Review","sentence":"She approved my pull request."},{"id":"ex-4","context":"Calendar","sentence":"They discussed the roadmap."},{"id":"ex-5","context":"On-call","sentence":"I restarted the worker."}],"tips":["didn''t + base (not didn''t went). Did + subject + base?","Have/has + PP is wrong with yesterday or a clock stamp."]}'::jsonb, 1, 1, 1, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000010', 'a1000000-0000-4000-8000-000000000003', 'past-simple-b1', 'B1 · Stamp vs yet', 'Past = closed stamp. Perfect = still open.', 'B1', '{"usage":"When: choose Past vs Perfect. Cue: yesterday / at 14:02 → Past; yet / already / so far → Perfect.","forms":{"affirmative":"V-ed / irregular past","negative":"didn''t + base verb","question":"Did + subject + base verb?"},"examples":[{"id":"ex-1","context":"Postmortem","sentence":"We resolved the incident yesterday."},{"id":"ex-2","context":"Standup","sentence":"She fixed the flaky job this morning."},{"id":"ex-3","context":"On-call","sentence":"They shipped the hotfix last night."},{"id":"ex-4","context":"Review","sentence":"Did you restart the pod yesterday?"},{"id":"ex-5","context":"Incident","sentence":"We didn''t redeploy after the check failed last night."}],"tips":["A clock in the sentence almost always means Past Simple.","this morning is Past if the window is closed; Perfect if it still matters now."]}'::jsonb, 1, 1, 2, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000011', 'a1000000-0000-4000-8000-000000000003', 'past-simple-b2', 'B2 · Register', 'Postmortem stamps stay Past Simple.', 'B2', '{"usage":"When: write the timeline. Cue: at HH:MM we shifted traffic — Past, not have shifted.","forms":{"affirmative":"V-ed / irregular past","negative":"didn''t + base verb","question":"Did + subject + base verb?"},"examples":[{"id":"ex-1","context":"Postmortem","sentence":"After we flipped the flag, errors dropped."},{"id":"ex-2","context":"Postmortem","sentence":"When the lock expired, the worker stalled."},{"id":"ex-3","context":"Postmortem","sentence":"They merged the fix after the war room."},{"id":"ex-4","context":"Review","sentence":"Did the canary fail before the rollback?"},{"id":"ex-5","context":"Incident","sentence":"We didn''t page anyone until the SEV was declared."}],"tips":["Postmortem clocks take Past Simple.","Keep Perfect for results that still matter (we have a monitor in)."]}'::jsonb, 1, 1, 3, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000012', 'a1000000-0000-4000-8000-000000000003', 'past-simple-c1', 'C1 · Incident stamp', 'Stamp = Past. Residual risk = Perfect.', 'C1', '{"usage":"When: split the story. Cue: at 14:02 we patched; we have not seen the error since.","forms":{"affirmative":"V-ed / irregular past","negative":"didn''t + base verb","question":"Did + subject + base verb?"},"examples":[{"id":"ex-1","context":"Incident","sentence":"At 14:02 we shifted traffic."},{"id":"ex-2","context":"Postmortem","sentence":"The RCA identified the bad index at 14:07."},{"id":"ex-3","context":"Slack","sentence":"At 14:18 we shifted EU traffic to the replica."},{"id":"ex-4","context":"Standup","sentence":"We closed the SEV-2 before handoff yesterday."},{"id":"ex-5","context":"Review","sentence":"QA signed the build after the war room."}],"tips":["Do not put have + PP next to at 14:02.","since / so far keep the window open → Perfect."]}'::jsonb, 1, 1, 4, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000013', 'a1000000-0000-4000-8000-000000000004', 'present-perfect-a2', 'A2 · Result', 'Past action, present result. Cue: yet / already / so far.', 'A2', '{"usage":"When: the result matters now. Cue: yet, already, so far, since. Not yesterday / at 14:02.","forms":{"affirmative":"have/has + past participle","negative":"haven''t / hasn''t + past participle","question":"Have/Has + subject + past participle?"},"examples":[{"id":"ex-1","context":"Incident","sentence":"We have fixed the login bug."},{"id":"ex-2","context":"PR","sentence":"I have used Postgres before."},{"id":"ex-3","context":"RFC","sentence":"She has updated the API contract."},{"id":"ex-4","context":"Standup","sentence":"They have finished the spike."},{"id":"ex-5","context":"Alert","sentence":"The error rate has dropped."}],"tips":["have/has + past participle. Have/Has + subject + PP?","yesterday and clock stamps take Past Simple."]}'::jsonb, 1, 1, 1, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000014', 'a1000000-0000-4000-8000-000000000004', 'present-perfect-b1', 'B1 · Yet vs yesterday', 'Perfect = open window. Past = closed stamp.', 'B1', '{"usage":"When: yet/already/since → Perfect; yesterday/last night/at 14:02 → Past Simple.","forms":{"affirmative":"have/has + past participle","negative":"haven''t / hasn''t + past participle","question":"Have/Has + subject + past participle?"},"examples":[{"id":"ex-1","context":"PR","sentence":"She has updated the schema this week."},{"id":"ex-2","context":"Postmortem","sentence":"She updated the schema yesterday."},{"id":"ex-3","context":"PR","sentence":"We haven''t shipped the patch yet."},{"id":"ex-4","context":"Review","sentence":"Has the canary recovered so far?"},{"id":"ex-5","context":"PR","sentence":"They have already fixed auth."}],"tips":["this week / today stay Perfect if the window is still open.","Do not answer have patched yesterday."]}'::jsonb, 1, 1, 2, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000015', 'a1000000-0000-4000-8000-000000000004', 'present-perfect-b2', 'B2 · Evidence', 'Review/RFC: what you have shipped, not a diary stamp.', 'B2', '{"usage":"When: evidence for a review. Cue: already / so far. A locked meeting time is not Perfect.","forms":{"affirmative":"have/has + past participle","negative":"haven''t / hasn''t + past participle","question":"Have/Has + subject + past participle?"},"examples":[{"id":"ex-1","context":"PR","sentence":"We have seen that timeout since Monday."},{"id":"ex-2","context":"PR","sentence":"I have used Postgres for three years."},{"id":"ex-3","context":"PR","sentence":"I have used Postgres in three teams so far."},{"id":"ex-4","context":"Review","sentence":"Has she merged the RFC yet?"},{"id":"ex-5","context":"Incident","sentence":"Errors have dropped since the cache warmup."}],"tips":["I have added tests is evidence. I added them at 09:10 is a stamp.","since Monday keeps Perfect; last Monday is Past."]}'::jsonb, 1, 1, 3, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000016', 'a1000000-0000-4000-8000-000000000004', 'present-perfect-c1', 'C1 · Still open', 'Residual error uses Perfect; the cutover stamp uses Past.', 'C1', '{"usage":"When: incident close. Cue: we have not reproduced it since; at 14:02 we failed over (Past).","forms":{"affirmative":"have/has + past participle","negative":"haven''t / hasn''t + past participle","question":"Have/Has + subject + past participle?"},"examples":[{"id":"ex-1","context":"Slack","sentence":"Result now: we have patched the leak."},{"id":"ex-2","context":"Incident","sentence":"Timeline: we patched the leak at 14:02."},{"id":"ex-3","context":"Standup","sentence":"We have mitigated the APAC 500s so far."},{"id":"ex-4","context":"PR","sentence":"Have you tested the hotfix yet?"},{"id":"ex-5","context":"Review","sentence":"She has already opened the dual-write RFC."}],"tips":["since + start time → Perfect.","A failover clock is Past Simple."]}'::jsonb, 1, 1, 4, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000017', 'a1000000-0000-4000-8000-000000000005', 'future-forms-a2', 'A2 · Plans', 'will = new decision. going to = plan you already have.', 'A2', '{"usage":"When: future action. Cue: Okay, I… → will; already planned / evidence → going to.","forms":{"affirmative":"am/is/are going to + V · will + V","negative":"isn''t/aren''t going to + V · won''t + V","question":"Are you going to + V? · Will you + V?"},"examples":[{"id":"ex-1","context":"Calendar","sentence":"We are going to migrate the database Friday."},{"id":"ex-2","context":"Offer","sentence":"I will help you debug that."},{"id":"ex-3","context":"Decision","sentence":"Okay — we will roll back."},{"id":"ex-4","context":"Calendar","sentence":"She is going to present the RFC."},{"id":"ex-5","context":"Offer","sentence":"I will send the logs after lunch."}],"tips":["will + base. am/is/are going to + base. Never will to or going to shipping.","A locked calendar uses Present Continuous (I am meeting)."]}'::jsonb, 1, 1, 1, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000018', 'a1000000-0000-4000-8000-000000000005', 'future-forms-b1', 'B1 · Will vs going to', 'Just decided = will. Already planned = going to.', 'B1', '{"usage":"When: pick will vs going to vs diary Continuous. Cue: Okay, I… → will; we already agreed → going to.","forms":{"affirmative":"am/is/are going to + V · will + V","negative":"isn''t/aren''t going to + V · won''t + V","question":"Are you going to + V? · Will you + V?"},"examples":[{"id":"ex-1","context":"Calendar","sentence":"We are going to run the cutover on Saturday."},{"id":"ex-2","context":"Decision","sentence":"The page just went red. Okay, I will disable the flag."},{"id":"ex-3","context":"Offer","sentence":"I will check Sentry after this deploy."},{"id":"ex-4","context":"Calendar","sentence":"They are going to rewrite the webhook next quarter."},{"id":"ex-5","context":"Review","sentence":"Will you join standup?"}],"tips":["Do not use will for a slot already on the calendar.","going to + base, not going to + V-ing."]}'::jsonb, 1, 1, 2, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000019', 'a1000000-0000-4000-8000-000000000005', 'future-forms-b2', 'B2 · Diary', 'Booked time → am meeting. Offer/decision → will.', 'B2', '{"usage":"When: RFC/calendar. Cue: Tuesday 11:00 → Present Continuous; I will send the doc → offer.","forms":{"affirmative":"I am meeting · we are going to freeze · I will ping","negative":"We aren''t going to ship dark","question":"Are you meeting security at 15:00?"},"examples":[{"id":"ex-1","context":"Calendar","sentence":"I am meeting security at 15:00."},{"id":"ex-2","context":"Calendar","sentence":"We are going to lock the release train tomorrow."},{"id":"ex-3","context":"Decision","sentence":"The build is red. I will ping the author."},{"id":"ex-4","context":"Alert","sentence":"Look at those 500s — it is going to fail the SLO."},{"id":"ex-5","context":"Review","sentence":"Are you meeting security at 15:00?"}],"tips":["Diary Continuous needs a time.","will not going to for a promise you make in the thread."]}'::jsonb, 1, 1, 3, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000020', 'a1000000-0000-4000-8000-000000000005', 'future-forms-c1', 'C1 · Call', 'War-room decision = will. Runbook plan = going to.', 'C1', '{"usage":"When: incident call. Cue: Okay, I will page them; the runbook says we are going to fail over.","forms":{"affirmative":"am/is/are going to + V · will + V","negative":"isn''t/aren''t going to + V · won''t + V","question":"Are you going to + V? · Will you + V?"},"examples":[{"id":"ex-1","context":"Incident","sentence":"Okay — we will shift EU traffic now."},{"id":"ex-2","context":"RFC","sentence":"The RFC says we are going to keep dual-write for a sprint."},{"id":"ex-3","context":"War room","sentence":"I am joining the bridge at 15:00."},{"id":"ex-4","context":"Offer","sentence":"Give me two minutes. I will paste the timeline."},{"id":"ex-5","context":"Review","sentence":"Will you shift EU traffic now?"}],"tips":["Do not mix will to. Modal+base and will+base only.","A completed failover at 14:02 is Past, not future."]}'::jsonb, 1, 1, 4, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000021', 'a1000000-0000-4000-8000-000000000006', 'modals-a2', 'A2 · Permission', 'can / should / must + base verb.', 'A2', '{"usage":"When: ability, advice, or rule. Cue: can (able), should (advice), must (policy). Always + base.","forms":{"affirmative":"can / could / should / must / might + base verb","negative":"can''t / shouldn''t / mustn''t / might not + base verb","question":"Can / Should / Must / Might + subject + base verb?"},"examples":[{"id":"ex-1","context":"Slack","sentence":"We should rollback the canary."},{"id":"ex-2","context":"PR","sentence":"You can merge after CI."},{"id":"ex-3","context":"Review","sentence":"She must add tests to this patch."},{"id":"ex-4","context":"Incident","sentence":"This might be a race in the worker."},{"id":"ex-5","context":"Deploy","sentence":"We must freeze the pipeline."}],"tips":["Never should to / must to / can to. Never musts.","must not = prohibition; do not have to = not required."]}'::jsonb, 1, 1, 1, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000022', 'a1000000-0000-4000-8000-000000000006', 'modals-b1', 'B1 · Advice vs must', 'should = advice. must = policy. might = uncertain.', 'B1', '{"usage":"When: pick the modal. Cue: policy/secret → must; review comment → should; hypothesis → might.","forms":{"affirmative":"should / must / can / could / might + base verb","negative":"shouldn''t / must not / couldn''t / might not + base verb","question":"Could you + V? · Should we + V?"},"examples":[{"id":"ex-1","context":"Review","sentence":"You should extract the webhook handler."},{"id":"ex-2","context":"Policy","sentence":"Authors must not merge their own RFC."},{"id":"ex-3","context":"Slack","sentence":"Could you tail the worker logs?"},{"id":"ex-4","context":"Ticket","sentence":"We could not reproduce the timeout yesterday."},{"id":"ex-5","context":"Alert","sentence":"This spike might be a stale cache."}],"tips":["Modal + base only (not can going, not should to).","must not is stronger than should not."]}'::jsonb, 1, 1, 2, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000023', 'a1000000-0000-4000-8000-000000000006', 'modals-b2', 'B2 · Register', 'RFC/review: must vs should vs might.', 'B2', '{"usage":"When: written review. Cue: must for security; should for style; might for a guess.","forms":{"affirmative":"Authors must + V · Reviewers should + V · This might + V","negative":"must not + V · should not + V · might not + V","question":"Must the RFC + V? · Should we + V?"},"examples":[{"id":"ex-1","context":"RFC","sentence":"Authors must document the rollback for dual-write."},{"id":"ex-2","context":"Review","sentence":"Reviewers should flag an unbounded retry."},{"id":"ex-3","context":"Docs","sentence":"The contract must reject unsigned tokens."},{"id":"ex-4","context":"Decision","sentence":"We should defer the Kafka cutover."},{"id":"ex-5","context":"PR","sentence":"This patch might race the outbox worker."}],"tips":["Do not hedge a hard policy with might.","could is past ability or polite option, not a security must."]}'::jsonb, 1, 1, 3, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000024', 'a1000000-0000-4000-8000-000000000006', 'modals-c1', 'C1 · Incident', 'War room: must (safety), might (hypothesis), should (next).', 'C1', '{"usage":"When: incident English. Cue: we must page; it might be DNS; we should freeze deploys.","forms":{"affirmative":"We must page · We should freeze · This might be replica lag","negative":"We must not fail over · This might not be the canary","question":"Must we page…? · Might this be…?"},"examples":[{"id":"ex-1","context":"War room","sentence":"We must page the primary for this SEV-1."},{"id":"ex-2","context":"Incident","sentence":"This might be replica lag, not a bad deploy."},{"id":"ex-3","context":"Alert","sentence":"We should silence the paging until triage ends."},{"id":"ex-4","context":"On-call","sentence":"I must not restart pods without a runbook step."},{"id":"ex-5","context":"Postmortem","sentence":"The RCA says we must treat p99 as a page."}],"tips":["Hypothesis = might/could, not must, until you have evidence.","Keep modal + base under pressure."]}'::jsonb, 1, 1, 4, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000025', 'a1000000-0000-4000-8000-000000000007', 'conditionals-a2', 'A2 · If facts', 'Zero: If + present, present. unless = if not.', 'A2', '{"usage":"When: a rule that is always true. Cue: If the job fails, it retries. No will in the if-clause.","forms":{"affirmative":"If + present, present / imperative / will + V","negative":"If + present, do not + V · Unless + present, do not + V","question":"If + present, should we + V?"},"examples":[{"id":"ex-1","context":"Docs","sentence":"If p99 exceeds 200ms, page the primary."},{"id":"ex-2","context":"CI","sentence":"If the pipeline is red, do not merge."},{"id":"ex-3","context":"Deploy","sentence":"If the canary fails, rollback traffic."},{"id":"ex-4","context":"Alert","sentence":"If Sentry spikes, open the runbook."},{"id":"ex-5","context":"Policy","sentence":"Unless review is done, we do not ship."}],"tips":["If-clause: present, not will. unless = if not.","First conditional (If + present, will) is for a real future."]}'::jsonb, 1, 1, 1, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000026', 'a1000000-0000-4000-8000-000000000007', 'conditionals-b1', 'B1 · If + will', 'Zero = always. First = real future. unless = if not.', 'B1', '{"usage":"When: pick 0 vs 1. Cue: always/policy → If + present, present; tomorrow/risk → If + present, will.","forms":{"affirmative":"If + present, will + V · If + present, present","negative":"Unless + present, will not + V · If + present, do not + V","question":"If + present, will we + V?"},"examples":[{"id":"ex-1","context":"Docs","sentence":"If p99 exceeds the SLO, the pager will page."},{"id":"ex-2","context":"Policy","sentence":"Unless QA signs, we will not ship."},{"id":"ex-3","context":"Incident","sentence":"If the replica lags, we will fail over."},{"id":"ex-4","context":"RFC","sentence":"If a caller sends a 409, the API rejects it."},{"id":"ex-5","context":"Slack","sentence":"Unless you disable the flag, checkout will fail."}],"tips":["Never If it will fail. The if-clause stays present.","unless CI passes = if CI does not pass."]}'::jsonb, 1, 1, 2, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000027', 'a1000000-0000-4000-8000-000000000007', 'conditionals-b2', 'B2 · Policy', 'RFC rules use zero; offers use first.', 'B2', '{"usage":"When: write policy vs a one-off offer. Cue: always → 0; If you approve, I will ship → 1.","forms":{"affirmative":"If + present, subject + must/should + V","negative":"Unless + present, we do not + V · If + present, must not + V","question":"If + present, must the worker + V?"},"examples":[{"id":"ex-1","context":"RFC","sentence":"If dual-write lags, the worker must halt."},{"id":"ex-2","context":"Docs","sentence":"If the contract breaks, callers must retry."},{"id":"ex-3","context":"Review","sentence":"If the retry is unbounded, we should block."},{"id":"ex-4","context":"Policy","sentence":"Unless the RFC is approved, we do not cut over."},{"id":"ex-5","context":"Ticket","sentence":"If the migration locks Postgres, abort it."}],"tips":["unless in a policy line still uses present, not will.","Do not write If you will approve."]}'::jsonb, 1, 1, 3, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000028', 'a1000000-0000-4000-8000-000000000007', 'conditionals-c1', 'C1 · War room', 'If + present for the live branch; will for the action.', 'C1', '{"usage":"When: incident branch. Cue: If error-rate stays over 2%, we will fail over.","forms":{"affirmative":"If + present, V and V · If + present, must + V","negative":"Unless + present, do not + V · If + present, should not + V","question":"If + present, do we page and freeze?"},"examples":[{"id":"ex-1","context":"War room","sentence":"If p99 exceeds the SLO, page the primary and freeze deploys."},{"id":"ex-2","context":"Incident","sentence":"If replica lag grows, fail over before the canary."},{"id":"ex-3","context":"Postmortem","sentence":"If timestamps are missing, the RCA is incomplete."},{"id":"ex-4","context":"Alert","sentence":"If the alert flaps, we should not fail over."},{"id":"ex-5","context":"On-call","sentence":"Unless the runbook matches, do not restart pods."}],"tips":["Keep will out of the if-clause even in a war room.","A finished branch (If it failed, we shifted) is Past, not first."]}'::jsonb, 1, 1, 4, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000029', 'a1000000-0000-4000-8000-000000000008', 'passives-a2', 'A2 · Be + PP', 'Object becomes subject. am/is/are/was/were + past participle.', 'A2', '{"usage":"When: the process matters more than the actor. Cue: was deployed, is blocked, were paged.","forms":{"affirmative":"was / were + past participle","negative":"was not / were not + past participle","question":"Was / Were + subject + past participle?"},"examples":[{"id":"ex-1","context":"Ticket","sentence":"The canary was rolled back at 14:11."},{"id":"ex-2","context":"Deploy","sentence":"The flag was disabled in production."},{"id":"ex-3","context":"PR","sentence":"The patch was approved after CI."},{"id":"ex-4","context":"Incident","sentence":"The replica was restarted at 09:40."},{"id":"ex-5","context":"Alert","sentence":"The pager was silenced by on-call."}],"tips":["was/were must agree: The jobs were queued. The job was queued.","Do not drop be (not The fix deployed yesterday as a passive)."]}'::jsonb, 1, 1, 1, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000030', 'a1000000-0000-4000-8000-000000000008', 'passives-b1', 'B1 · Who vs process', 'Passive hides the actor; active names the owner.', 'B1', '{"usage":"When: choose voice. Cue: process/status → passive; owner/accountability → active.","forms":{"affirmative":"We rolled back · The canary was rolled back","negative":"We did not enable · The flag was not enabled","question":"Did you rotate it? · Was the secret rotated?"},"examples":[{"id":"ex-1","context":"Ticket","sentence":"QA found the bug, and the bug was logged on the ticket."},{"id":"ex-2","context":"Incident","sentence":"On-call restarted the replica after it was drained."},{"id":"ex-3","context":"PR","sentence":"Reviewers approved the patch once tests were added."},{"id":"ex-4","context":"Deploy","sentence":"We disabled the flag after checkout was affected."},{"id":"ex-5","context":"Alert","sentence":"Sentry grouped the 500s after they were sampled."}],"tips":["by + actor only when the actor matters.","Incident stamps still need the right tense: was patched at 14:02."]}'::jsonb, 1, 1, 2, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000031', 'a1000000-0000-4000-8000-000000000008', 'passives-b2', 'B2 · RFC', 'RFC status lines prefer passive process English.', 'B2', '{"usage":"When: written status. Cue: Traffic is routed / keys are rotated — process, not I rotated.","forms":{"affirmative":"Traffic was shifted · The schema was migrated","negative":"Writes were not accepted · The flag was not defaulted on","question":"Was dual-write documented? · Were retries bounded?"},"examples":[{"id":"ex-1","context":"RFC","sentence":"Dual-write was documented as a requirement."},{"id":"ex-2","context":"Ticket","sentence":"The schema was migrated during the freeze."},{"id":"ex-3","context":"Review","sentence":"Unbounded retries were flagged on the worker."},{"id":"ex-4","context":"Docs","sentence":"Rollback was listed as a mandatory step."},{"id":"ex-5","context":"Policy","sentence":"Raw secrets were forbidden in application logs."}],"tips":["Keep be + PP. Avoid is routing for a finished design.","Stative: the service is owned by… is OK; is owning is not."]}'::jsonb, 1, 1, 3, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000032', 'a1000000-0000-4000-8000-000000000008', 'passives-c1', 'C1 · Incident', 'Passive for the change; active for the owner of the next step.', 'C1', '{"usage":"When: war room. Cue: Traffic was shifted at 14:02; I am paging SRE now.","forms":{"affirmative":"At TIME, X was + V3; Y was + V3 by TIME","negative":"The canary was not promoted; traffic was not restored yet","question":"Was p99 restored by 14:19? · Were pods drained first?"},"examples":[{"id":"ex-1","context":"Slack","sentence":"Could you confirm pods were drained before failover?"},{"id":"ex-2","context":"War room","sentence":"At 14:11 the canary was rolled back."},{"id":"ex-3","context":"Standup","sentence":"p99 was restored by 14:19 after the rollback."},{"id":"ex-4","context":"PR","sentence":"Tests were added before the patch was approved."},{"id":"ex-5","context":"Incident","sentence":"The fallback was not dropped while dual-write was open."}],"tips":["Stamp + passive Past. Live action + active Continuous.","Do not write have been shifted at 14:02."]}'::jsonb, 1, 1, 4, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000033', 'a1000000-0000-4000-8000-000000000009', 'articles-a2', 'A2 · A / an / the', 'a/an = one new count. the = already known. ∅ = generic uncount.', 'A2', '{"usage":"When: name a thing. Cue: a retry (first), the retry (known), latency (generic uncount).","forms":{"affirmative":"a JWT · an RFC · the cache · latency (no article)","negative":"not a latency · not an RFC yet · not the old cache","question":"Do we need an RFC? · Is the cache warm?"},"examples":[{"id":"ex-1","context":"Slack","sentence":"Please open an RFC for the dual-write window."},{"id":"ex-2","context":"Standup","sentence":"I added an index on the billing table."},{"id":"ex-3","context":"PR","sentence":"Track latency in the SLO dashboard."},{"id":"ex-4","context":"Ticket","sentence":"There is a leak in checkout."},{"id":"ex-5","context":"Docs","sentence":"Postgres is fine; the replica is lagging."}],"tips":["an before a vowel sound (an RFC, an hour). a before a consonant sound (a unique key).","No article with generic latency / production / traffic."]}'::jsonb, 1, 1, 1, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000034', 'a1000000-0000-4000-8000-000000000009', 'articles-b1', 'B1 · Generic vs the', '∅ for generic; the when both of you can point to it.', 'B1', '{"usage":"When: pick a/an/the/∅. Cue: first mention → a/an; shared channel object → the; uncount generic → ∅.","forms":{"affirmative":"an RFC, then the RFC · an index, then the index","negative":"not a latency · not a primary (if there is one primary)","question":"Do we need an RFC or the RFC from last quarter?"},"examples":[{"id":"ex-1","context":"RFC","sentence":"We need an RFC, not the RFC from last quarter."},{"id":"ex-2","context":"Incident","sentence":"Cache is cold; the cache needs warmup."},{"id":"ex-3","context":"Alert","sentence":"Use latency, not a latency, in the SLO."},{"id":"ex-4","context":"PR","sentence":"I added an index; the index is unused."},{"id":"ex-5","context":"Ticket","sentence":"There is a leak; the leak is in billing."}],"tips":["the API in this thread is identified; APIs in general can be ∅ or plural.","Do not write a latency or the production as generic mass nouns."]}'::jsonb, 1, 1, 2, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000035', 'a1000000-0000-4000-8000-000000000009', 'articles-b2', 'B2 · Spec', 'RFC: the + identified component; ∅ + generic quality.', 'B2', '{"usage":"When: spec English. Cue: the checkout service vs reliability as a generic noun.","forms":{"affirmative":"an SLO · the token · Production secrets · a warmup","negative":"not an open-ended dual-write · not a retry without a bound","question":"Does the RFC define an SLO?"},"examples":[{"id":"ex-1","context":"RFC","sentence":"The RFC must define an SLO for p99."},{"id":"ex-2","context":"Docs","sentence":"Callers send a token; the token is validated at the gateway."},{"id":"ex-3","context":"Review","sentence":"Avoid a retry without a bound; bound the retry."},{"id":"ex-4","context":"Policy","sentence":"Production secrets stay out of the mobile bundle."},{"id":"ex-5","context":"Ticket","sentence":"The migration needs a warmup for the cache."}],"tips":["the when the spec already named the component.","a/an for a new count (a circuit breaker)."]}'::jsonb, 1, 1, 3, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000036', 'a1000000-0000-4000-8000-000000000009', 'articles-c1', 'C1 · Scope', 'Incident scope: the blast radius vs generic traffic.', 'C1', '{"usage":"When: scope a blast. Cue: the payment class; traffic/latency stay ∅ unless identified.","forms":{"affirmative":"Latency is the page condition · Traffic was shed","negative":"not a latency · not a production page (if none is warranted)","question":"Is RCA still open? · Did we lose the primary?"},"examples":[{"id":"ex-1","context":"War room","sentence":"Latency, not a latency, is the page condition."},{"id":"ex-2","context":"Incident","sentence":"Traffic was shed; the primary was saturated."},{"id":"ex-3","context":"Postmortem","sentence":"The canary was fine; traffic was the problem."},{"id":"ex-4","context":"Alert","sentence":"p99 is red; do not wait for a second page."},{"id":"ex-5","context":"On-call","sentence":"On-call watches the dashboard after the pager is muted."}],"tips":["Name the identified cluster with the.","Do not article generic production."]}'::jsonb, 1, 1, 4, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000037', 'a1000000-0000-4000-8000-000000000010', 'reported-speech-a2', 'A2 · Say / tell', 'tell + person. say (+ that). Quote → report.', 'A2', '{"usage":"When: report a message. Cue: she told me; he said the job failed. tell needs an object.","forms":{"affirmative":"She said (that) + past clause","negative":"She said (that) + past negative","question":"Did she say (that) + past clause?"},"examples":[{"id":"ex-1","context":"Slack","sentence":"She said the flag was already off."},{"id":"ex-2","context":"Standup","sentence":"He said the pipeline was green."},{"id":"ex-3","context":"PR","sentence":"She said she needed another review."},{"id":"ex-4","context":"Incident","sentence":"They said the replica was lagging."},{"id":"ex-5","context":"Deploy","sentence":"He said they rolled back the canary."}],"tips":["tell + object (+ that). say does not need an object.","Keep tense if the reporting verb is present; backshift if it is past."]}'::jsonb, 1, 1, 1, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000038', 'a1000000-0000-4000-8000-000000000010', 'reported-speech-b1', 'B1 · Backshift', 'Reporting verb in the past → shift the inner tense.', 'B1', '{"usage":"When: She said… Cue: said/told (past) → backshift; says (present) → keep the original tense.","forms":{"affirmative":"She told us + past · She said + past · She asked if + could","negative":"She told me the bug was not in billing","question":"Did he say the tests were missing?"},"examples":[{"id":"ex-1","context":"Slack","sentence":"Quote: The flag is off. Report: she said the experiment flag was off."},{"id":"ex-2","context":"Standup","sentence":"He told us the pipeline was still red."},{"id":"ex-3","context":"PR","sentence":"She asked if we could merge after CI."},{"id":"ex-4","context":"Incident","sentence":"They told on-call the replica had lagged."},{"id":"ex-5","context":"Review","sentence":"He said the tests were missing on the spec, not are missing."}],"tips":["will → would; Present → Past; Past → Past Perfect when the report is past.","tell me / tell the team — never He told that without an object."]}'::jsonb, 1, 1, 2, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000039', 'a1000000-0000-4000-8000-000000000010', 'reported-speech-b2', 'B2 · Register', 'Reviews report claims; keep or shift from the reporting verb.', 'B2', '{"usage":"When: quote a review. Cue: The author says the API is idempotent (present, still true).","forms":{"affirmative":"The author wrote that + would/past","negative":"QA reported that checkout had not passed","question":"Did the reviewer note that retries were unbounded?"},"examples":[{"id":"ex-1","context":"RFC","sentence":"The author wrote that dual-write would stay one sprint."},{"id":"ex-2","context":"Review","sentence":"The reviewer noted that retries were unbounded."},{"id":"ex-3","context":"Docs","sentence":"The runbook stated that rollback was mandatory."},{"id":"ex-4","context":"Ticket","sentence":"QA reported that checkout had failed twice."},{"id":"ex-5","context":"Policy","sentence":"Legal said the contract must reject unsigned tokens."}],"tips":["If the claim is still true, you may keep present after said.","Do not drop the object after tell."]}'::jsonb, 1, 1, 3, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000040', 'a1000000-0000-4000-8000-000000000010', 'reported-speech-c1', 'C1 · Incident report', 'Report war-room claims with backshift and objects.', 'C1', '{"usage":"When: postmortem. Cue: SRE told us the node had already failed over.","forms":{"affirmative":"The primary reported that + had + V3","negative":"On-call said they could not reach the owner","question":"Did she say the leak was already patched?"},"examples":[{"id":"ex-1","context":"War room","sentence":"The primary reported that p99 had crossed the SLO."},{"id":"ex-2","context":"Incident","sentence":"She said the leak was already patched at 14:22."},{"id":"ex-3","context":"Postmortem","sentence":"On-call said they could not reach the runbook owner."},{"id":"ex-4","context":"Alert","sentence":"He said the pager should not have paged a silenced route."},{"id":"ex-5","context":"Deploy","sentence":"They said the canary had been rolled back before cutover."}],"tips":["Past reporting + earlier action → Past Perfect.","Use told us / said that — not told that."]}'::jsonb, 1, 1, 4, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000041', 'a1000000-0000-4000-8000-000000000011', 'present-perfect-continuous-a2', 'A2 · For / since', 'When an action started earlier and is still running. Cue: for / since / all morning.', 'A2', '{"usage":"When: live work that started earlier and continues. Cue: for, since, all morning.","forms":{"affirmative":"have/has been + V-ing","negative":"haven''t/hasn''t been + V-ing","question":"Have/Has + subject + been + V-ing?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"I have been investigating the 500s all morning."},{"id":"ex-2","context":"Slack","sentence":"She has been syncing the replica for an hour."},{"id":"ex-3","context":"PR","sentence":"We have been reviewing the dual-write RFC since Monday."},{"id":"ex-4","context":"Ticket","sentence":"QA has been testing the hotfix for two hours."},{"id":"ex-5","context":"On-call","sentence":"They have been paging the primary since 09:00."}],"tips":["Do not use Present Perfect Continuous for a finished stamp (use Past Simple).","for + duration; since + start point."]}'::jsonb, 1, 1, 1, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000042', 'a1000000-0000-4000-8000-000000000011', 'present-perfect-continuous-b1', 'B1 · Still running vs done', 'Pick Continuous Perfect vs Simple Perfect / Past when the hunt is open or closed.', 'B1', '{"usage":"When: open hunt → have been + V-ing. Cue: still / so far / all day vs finished stamp.","forms":{"affirmative":"have/has been + V-ing (open)","negative":"have/has + PP (result now) vs Past (stamp)","question":"Have you been …? vs Have you … yet?"},"examples":[{"id":"ex-1","context":"Incident","sentence":"We have been mitigating the leak since 14:02."},{"id":"ex-2","context":"Slack","sentence":"Have you finished the RCA yet?"},{"id":"ex-3","context":"Standup","sentence":"I have been pairing on the flaky spec all sprint."},{"id":"ex-4","context":"PR","sentence":"She has already opened the dual-write RFC."},{"id":"ex-5","context":"Review","sentence":"They closed the SEV-2 yesterday."}],"tips":["Open activity → have been + V-ing. Finished result → have + PP or Past.","yet usually wants Present Perfect Simple, not Continuous."]}'::jsonb, 1, 1, 2, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000043', 'a1000000-0000-4000-8000-000000000011', 'present-perfect-continuous-b2', 'B2 · Status updates', 'Write standup/Slack status with have been + V-ing without overclaiming a result.', 'B2', '{"usage":"When: status that is still in flight. Cue: still / currently / all morning.","forms":{"affirmative":"I''ve/we''ve been + V-ing","negative":"haven''t been + V-ing","question":"Could you confirm how long … has been …?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"We''ve been warming the cache since the deploy."},{"id":"ex-2","context":"Slack","sentence":"Could you check how long the replica has been lagging?"},{"id":"ex-3","context":"PR","sentence":"I have been documenting the rollback path."},{"id":"ex-4","context":"RFC","sentence":"Authors have been drafting the dual-write window."},{"id":"ex-5","context":"Alert","sentence":"p99 has been spiking for twenty minutes."}],"tips":["Status Continuous Perfect does not mark the incident resolved.","Ask duration with how long + have/has been + V-ing."]}'::jsonb, 1, 1, 3, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000044', 'a1000000-0000-4000-8000-000000000011', 'present-perfect-continuous-c1', 'C1 · War-room narrative', 'Separate the ongoing hunt from the timestamped move in one update.', 'C1', '{"usage":"When: war-room voice. Cue: still investigating vs at 14:11 we shifted.","forms":{"affirmative":"have been + V-ing (hunt) + Past stamp (move)","negative":"Do not put have been + V-ing next to at 14:02 as the key.","question":"Have we been … while traffic was shifted?"},"examples":[{"id":"ex-1","context":"War room","sentence":"We have been tracing checkout 500s while EU traffic was shifted."},{"id":"ex-2","context":"Incident","sentence":"At 14:11 we rolled the canary back."},{"id":"ex-3","context":"Slack","sentence":"Please confirm we have been paging the primary since the SEV-1."},{"id":"ex-4","context":"Postmortem","sentence":"On-call had been investigating for forty minutes before failover."},{"id":"ex-5","context":"Standup","sentence":"We are still syncing the replica after the cutover."}],"tips":["Hunt = have been + V-ing. Clocked move = Past Simple.","Do not claim resolution with Continuous Perfect alone."]}'::jsonb, 1, 1, 4, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000045', 'a1000000-0000-4000-8000-000000000012', 'verb-patterns-a2', 'A2 · Need to / avoid -ing', 'After need/want use to + base. After avoid/keep use V-ing.', 'A2', '{"usage":"When: choose to-infinitive vs gerund after common SE verbs. Cue: need to, avoid -ing.","forms":{"affirmative":"need/want/decide + to + base; avoid/keep/consider + V-ing","negative":"not need to + base; avoid + V-ing","question":"Do we need to …? / Should we avoid …?"},"examples":[{"id":"ex-1","context":"Slack","sentence":"We need to disable the flag before the deploy."},{"id":"ex-2","context":"PR","sentence":"Please avoid merging during the freeze."},{"id":"ex-3","context":"Standup","sentence":"I want to pair on the flaky spec today."},{"id":"ex-4","context":"Ticket","sentence":"QA decided to retest the hotfix tonight."},{"id":"ex-5","context":"Review","sentence":"Keep documenting the rollback path."}],"tips":["need/want/decide → to + base. Never need to disabling.","avoid/keep/consider → V-ing. Never avoid to merge."]}'::jsonb, 1, 1, 1, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000046', 'a1000000-0000-4000-8000-000000000012', 'verb-patterns-b1', 'B1 · Pick the pattern', 'Choose to-infinitive vs gerund from the verb cue in Slack/PR.', 'B1', '{"usage":"When: two real patterns compete. Cue: the verb before the blank.","forms":{"affirmative":"verb cue picks to + base or V-ing","negative":"wrong pattern after the cue verb","question":"Should we avoid … or need to …?"},"examples":[{"id":"ex-1","context":"PR","sentence":"Reviewers suggested delaying the cutover."},{"id":"ex-2","context":"Slack","sentence":"We need to page the primary for this SEV-1."},{"id":"ex-3","context":"Standup","sentence":"I keep seeing 429s on checkout."},{"id":"ex-4","context":"RFC","sentence":"Authors agreed to keep dual-write for a sprint."},{"id":"ex-5","context":"Deploy","sentence":"Please avoid restarting pods during the canary."}],"tips":["suggest/avoid/keep/consider → V-ing.","need/want/decide/agree → to + base."]}'::jsonb, 1, 1, 2, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000047', 'a1000000-0000-4000-8000-000000000012', 'verb-patterns-b2', 'B2 · Review voice', 'Write polite review asks with the right pattern.', 'B2', '{"usage":"When: PR/RFC comments. Cue: could you + base; avoid/consider + V-ing.","forms":{"affirmative":"Could you + base; consider/avoid + V-ing","negative":"Do not write could you to merge.","question":"Could you …? / Would you mind …-ing?"},"examples":[{"id":"ex-1","context":"PR","sentence":"Could you extract the webhook handler?"},{"id":"ex-2","context":"Review","sentence":"Please consider adding an idempotency token."},{"id":"ex-3","context":"Slack","sentence":"Would you mind reviewing the dual-write RFC?"},{"id":"ex-4","context":"RFC","sentence":"Authors should avoid storing raw secrets."},{"id":"ex-5","context":"Ticket","sentence":"We need to document the rollback before ship."}],"tips":["Polite ask: could you + base.","consider/mind/avoid → V-ing."]}'::jsonb, 1, 1, 3, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000048', 'a1000000-0000-4000-8000-000000000012', 'verb-patterns-c1', 'C1 · Incident decisions', 'Chain need to / avoid / keep during a SEV without broken patterns.', 'C1', '{"usage":"When: war-room moves. Cue: we need to fail over; avoid flapping the canary.","forms":{"affirmative":"need to + base; avoid + V-ing; keep + V-ing","negative":"No need to to / avoid to","question":"Do we need to … or keep …-ing?"},"examples":[{"id":"ex-1","context":"War room","sentence":"We need to shift EU traffic now."},{"id":"ex-2","context":"Incident","sentence":"Avoid flapping the canary on one spike."},{"id":"ex-3","context":"Slack","sentence":"Please keep tracing the 500s while we page."},{"id":"ex-4","context":"Postmortem","sentence":"On-call decided to fail over after forty minutes."},{"id":"ex-5","context":"Standup","sentence":"We agreed to freeze deploys until p99 recovers."}],"tips":["Decision verbs (decide/agree/need) take to + base.","avoid/keep take V-ing even under SEV pressure."]}'::jsonb, 1, 1, 4, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000049', 'a1000000-0000-4000-8000-000000000013', 'connectors-a2', 'A2 · Because / so', 'Link cause and result in one update. Cue: because (reason), so (result).', 'A2', '{"usage":"When: join two workplace clauses. Cue: because / so.","forms":{"affirmative":"… because … / … so …","negative":"Do not stack because so.","question":"Why…? → because …"},"examples":[{"id":"ex-1","context":"Slack","sentence":"p99 spiked, so we rolled the canary."},{"id":"ex-2","context":"Standup","sentence":"I paired with QA because the spec was flaky."},{"id":"ex-3","context":"PR","sentence":"Coverage dropped, so the pipeline blocked the deploy."},{"id":"ex-4","context":"Ticket","sentence":"We disabled the flag because checkout returned 500s."},{"id":"ex-5","context":"Alert","sentence":"The replica lagged, so on-call paged the primary."}],"tips":["because introduces the reason. so introduces the result.","One linker per join — do not write because so."]}'::jsonb, 1, 1, 1, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000050', 'a1000000-0000-4000-8000-000000000013', 'connectors-b1', 'B1 · However / so / because', 'Pick the linker that matches contrast vs cause vs result.', 'B1', '{"usage":"When: three linkers compete. Cue: contrast → however; reason → because; result → so.","forms":{"affirmative":"however (contrast), because (reason), so (result)","negative":"Wrong linker for the logical relation","question":"Which linker fits the relation?"},"examples":[{"id":"ex-1","context":"Review","sentence":"The RFC is clear; however, dual-write still lacks a rollback."},{"id":"ex-2","context":"Slack","sentence":"CI is green, so we can merge after lunch."},{"id":"ex-3","context":"Incident","sentence":"We failed over because p99 burned the SLO."},{"id":"ex-4","context":"PR","sentence":"Tests pass; however, the webhook contract changed."},{"id":"ex-5","context":"Standup","sentence":"I blocked the deploy because the canary flapped."}],"tips":["however = contrast. because = reason. so = result.","Do not use however for pure cause."]}'::jsonb, 1, 1, 2, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000051', 'a1000000-0000-4000-8000-000000000013', 'connectors-b2', 'B2 · Which means', 'Add a consequence clause after a metric or decision.', 'B2', '{"usage":"When: explain impact. Cue: which means + clause.","forms":{"affirmative":"…, which means …","negative":"Do not write which mean / that means without a clause","question":"What does this change mean for …?"},"examples":[{"id":"ex-1","context":"RFC","sentence":"We keep dual-write one sprint, which means higher write load."},{"id":"ex-2","context":"Slack","sentence":"p99 is still red, which means we should freeze deploys."},{"id":"ex-3","context":"PR","sentence":"Coverage dropped, which means the pipeline will block."},{"id":"ex-4","context":"Review","sentence":"The token is required, which means unsigned JWTs fail."},{"id":"ex-5","context":"Standup","sentence":"EU traffic shifted, which means APAC stays on primary."}],"tips":["which means + full clause (subject + verb).","Use it after a comma to spell the impact."]}'::jsonb, 1, 1, 3, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

insert into public.grammar_lessons (id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published)
values ('a2000000-0000-4000-8000-000000000052', 'a1000000-0000-4000-8000-000000000013', 'connectors-c1', 'C1 · Incident narrative', 'Chain because / so / however / which means in a short RCA-style update.', 'C1', '{"usage":"When: war-room or postmortem voice. Cue: mix linkers without doubling.","forms":{"affirmative":"stamp + so/because + however + which means","negative":"No because so / however because stacks","question":"Could you rewrite the timeline with clear linkers?"},"examples":[{"id":"ex-1","context":"War room","sentence":"p99 burned the SLO, so we shifted EU traffic."},{"id":"ex-2","context":"Incident","sentence":"We paged the primary because the replica lagged."},{"id":"ex-3","context":"Postmortem","sentence":"The canary looked healthy; however, checkout still returned 500s."},{"id":"ex-4","context":"Slack","sentence":"Dual-write stayed open, which means billing saw duplicates."},{"id":"ex-5","context":"Standup","sentence":"Please confirm the timeline uses because and so correctly."}],"tips":["One clear relation per linker.","Ask for a rewrite when the RCA stacks because so."]}'::jsonb, 1, 1, 4, true)
on conflict (topic_id, slug) do update set title = excluded.title, description = excluded.description, level = excluded.level, content = excluded.content, content_schema_version = excluded.content_schema_version, content_revision = excluded.content_revision, sort_order = excluded.sort_order, published = excluded.published, updated_at = now();

